 return <section className="rounded-xl border bg-white p-5 space-y-4"><button type="button" onClick={onChangeTemplate} className="rounded border px-3 py-2 text-sm font-bold">← Choose another message</button><h2 className="font-bold text-lg">{selected.name}</h2><p className="text-sm text-slate-600">Message body and title only. The existing approved Basic Brand Kit supplies the header, logo, signature, utility links and footer. This draft does not change live sending routes.</p>{isMembership&&<div className="rounded-xl border border-blue-200 p-4 space-y-3"><h3 className="font-bold">1. Audience — Membership database</h3><div className="flex flex-wrap gap-2"><button type="button" className={"rounded border px-3 py-2 text-sm "+(audienceKind==='applications'?'bg-blue-700 text-white':'')} onClick={()=>setAudienceKind('applications')}>Applicants / invited guests</button><button type="button" className={"rounded border px-3 py-2 text-sm "+(audienceKind==='members'?'bg-blue-700 text-white':'')} onClick={()=>setAudienceKind('members')}>Members</button></div><input className="w-full rounded border p-2" placeholder="Search name, email or status" value={audienceSearch} onChange={e=>setAudienceSearch(e.target.value)}/><div className="text-sm">{recipientIds.length} selected · {audience.length} records loaded · {matchingAudience.length} matching</div><div className="flex gap-3 text-xs"><button type="button" className="underline" onClick={()=>setRecipientIds(matchingAudience.filter(r=>r.email).map(r=>r.id))}>Select matching with email</button><button type="button" className="underline" onClick={()=>setRecipientIds([])}>Deselect all</button></div><div className="max-h-44 overflow-auto divide-y">{matchingAudience.slice(0,150).map(r=><label key={r.id} className="flex items-center gap-2 py-2 text-sm"><input type="checkbox" checked={recipientIds.includes(r.id)} onChange={e=>setRecipientIds(old=>e.target.checked?[...old,r.id]:old.filter(id=>id!==r.id))}/><span>{r.full_name||'Name unavailable'} · {r.email||'No email'} · {r.payment_status||r.membership_status||'status unavailable'}</span></label>)}</div>{audienceError&&<p role="alert" className="text-red-700">{audienceError}</p>}<p className="text-xs text-amber-800">Audience selection and personalised preview only. Sending remains disabled until the shared delivery route and permissions are verified.</p></div>}<h3 className="font-bold">{isMembership?'2. Review and edit message':'Message editor'}</h3><label className="block text-sm font-semibold">Email subject<input className="mt-1 w-full rounded border p-2" value={subject} onChange={e=>setSubject(e.target.value)}/></label><label className="block text-sm font-semibold">Header title<input className="mt-1 w-full rounded border p-2" value={title} onChange={e=>setTitle(e.target.value)}/></label><label className="block text-sm font-semibold">Header subtitle<input className="mt-1 w-full rounded border p-2" value={subtitle} onChange={e=>setSubtitle(e.target.value)}/></label><RichMessageEditor value={plain} htmlValue={html} setValue={setPlain} setHtmlValue={setHtml} brand={brandKit?.colours||{}}/><details><summary className="cursor-pointer text-sm font-semibold">Plain-text version</summary><textarea rows={10} className="w-full mt-2 rounded border p-2" value={plain} onChange={e=>setPlain(e.target.value)}/></details>{isMembership&&<div className="rounded-xl border p-4 space-y-3"><h3 className="font-bold">3. Actual branded email preview</h3><div className="text-sm">Previewing {recipient?.full_name||'sample recipient'} · {recipientIds.length} selected</div><div className="text-xs text-slate-600">Basic branded — approved shared header, signature, utility links and footer. Dynamic private/payment links are placeholders in preview.</div><iframe title="Membership branded email preview" sandbox="" srcDoc={brandedPreview} className="w-full min-h-[620px] rounded border bg-white"/><h3 className="font-bold">4. Review delivery</h3><p className="text-sm">{recipientIds.length} recipients selected. Sending is not enabled for this draft workflow; the existing approved membership sending routes remain unchanged.</p></div>}<button type="button" disabled={busy} onClick={save} className="rounded bg-slate-900 text-white px-4 py-2 font-semibold">{busy?'Saving…':'Save editable draft'}</button> {isMembership&&<button type="button" disabled={busy||record?.status!=='draft'} onClick={approve} className="rounded bg-blue-700 text-white px-4 py-2 font-semibold disabled:opacity-40">Approve saved template for future emails</button>}{isMembership&&<span className="text-sm font-semibold">Status: {record?.status||'not loaded'}</span>}{notice&&<p role="status" className="text-green-700">{notice}</p>}{error&&<p role="alert" className="text-red-700">{error}</p>}</section>;
