 const [record,setRecord]=useState(null),[subject,setSubject]=useState(starter?.subject||''),[plain,setPlain]=useState(starter?.plainText?.replace(/\n\nYours in sport,[\s\S]*$/,'')||''),[html,setHtml]=useState(''),[mode,setMode]=useState('html'),[preview,setPreview]=useState(''),[busy,setBusy]=useState(''),[error,setError]=useState(''),[notice,setNotice]=useState('');
 useEffect(()=>{let alive=true;(async()=>{try{const rows=await base44.entities.CommunicationTemplate.filter({tenant_id:user.active_tenant_id,purpose:'guest_session_followup'},'-updated_date',20);if(!alive)return;const t=(rows||[]).find(x=>x.status==='approved')||rows?.[0];if(t){setRecord(t);setSubject(t.subject_template||'');setPlain(t.plain_text_template||'');setHtml(t.html_template||'')}}catch(e){if(alive)setError(e.message)}})();return()=>{alive=false}},[user?.active_tenant_id]);
 const [sessions,setSessions]=useState([]),[sessionId,setSessionId]=useState(''),[bookings,setBookings]=useState([]),[attendance,setAttendance]=useState({}),[chosen,setChosen]=useState([]),[delivery,setDelivery]=useState([]),[guestSearch,setGuestSearch]=useState(''),[ctaInsert,setCtaInsert]=useState(null);
 const refreshSessions=async()=>{setError('');try{const rows=await base44.entities.GuestSessionLink.filter({tenant_id:user.active_tenant_id},'-created_date',100);setSessions(rows||[]);setNotice('Session list refreshed.')}catch(e){setError(e.message||'Cannot load sessions')}};
 useEffect(()=>{refreshSessions()},[user?.active_tenant_id]);
 const refreshRecipients=async(id=sessionId)=>{if(!id)return;setBusy('recipients');setError('');try{const [booked,attended]=await Promise.all([base44.entities.GuestSessionBooking.filter({tenant_id:user.active_tenant_id,session_link_id:id},'-created_date',150),base44.functions.invoke('guestSessionBooking',{action:'attendance_list',sessionId:id})]);if(attended.data?.error)throw Error(attended.data.error);setBookings(booked||[]);setAttendance(Object.fromEntries((attended.data?.attendance||[]).map(a=>[a.bookingId,a.status])));setChosen([]);setDelivery([])}catch(e){setError(e.message||'Cannot load recipients')}finally{setBusy('')}};
