 const sendSelected=async()=>{if(!chosen.length)return;if(!window.confirm('Send the approved guest follow-up to '+chosen.length+' selected guests now?'))return;setBusy('send');setError('');try{const r=await invoke({action:'followup_send',sessionId,bookingIds:chosen,confirmSend:true});setDelivery(r.results||[]);setNotice('Completed: '+(r.results||[]).filter(x=>x.status==='sent').length+' sent; '+(r.results||[]).filter(x=>x.status!=='sent').length+' skipped or failed.')}catch(e){setError(e.message||'Send failed')}finally{setBusy('')}};
 const invoke=async(payload)=>{const response=await base44.functions.invoke('guestSessionBooking',payload);if(response.data?.error)throw Error(response.data.error);return response.data};
 const addAction=(kind)=>{const membership=kind==='membership';const url=membership?'https://www.clarepickleball.ie/membership':'https://www.clarepickleball.ie/book';const label=membership?'Join Clare Pickleball':'Book Another Guest Session';const guidance=membership?'Ready to become a member? Tap the button below to join.':'Would you like another game before deciding? Tap the button below to choose a session.';const background=membership?'#081342':'#FACC15';const foreground=membership?'#ffffff':'#081342';const snippet='<p style="margin:20px 0 8px;font-size:15px">'+guidance+'</p><p style="margin:10px 0 24px"><a href="'+url+'" style="display:inline-block;padding:13px 22px;background:'+background+';color:'+foreground+';font-weight:bold;text-decoration:none;border-radius:7px">'+label+'</a></p>';setMode('html');setCtaInsert(snippet);setNotice(label+' button inserted in the message. Review it and save a draft before approving.');};
 const draftData=()=>({owner_scope:'tenant',tenant_id:user.active_tenant_id,club_id:user.active_club_id,module:'Session Bookings',name:'Guest Booking — Thank You & Next Steps',purpose:'guest_session_followup',version:String(Date.now()),subject_template:subject,plain_text_template:plain,html_template:html});
 const save=async()=>{setBusy('save');setError('');try{if(!subject.trim()||!plain.trim())throw Error('Subject and message body are required');const rows=await base44.entities.CommunicationTemplate.filter({tenant_id:user.active_tenant_id,purpose:'guest_session_followup'},'-updated_date',30);const draft=rows.find(t=>t.status==='draft'&&(!t.club_id||t.club_id===user.active_club_id));const data={...draftData(),status:'draft'};const result=draft?await base44.entities.CommunicationTemplate.update(draft.id,data):await base44.entities.CommunicationTemplate.create(data);setRecord(result);setNotice('Draft saved successfully. No email sent.')}catch(e){setError(e.message||'Could not save draft')}finally{setBusy('')}};
 const approve=async()=>{if(!window.confirm('Approve the saved Guest Thank You template for future sending?'))return;setBusy('approve');setError('');try{const rows=await base44.entities.CommunicationTemplate.filter({tenant_id:user.active_tenant_id,purpose:'guest_session_followup'},'-updated_date',30);const draft=rows.find(t=>t.status==='draft'&&(!t.club_id||t.club_id===user.active_club_id));if(!draft){const existing=rows.find(t=>t.status==='approved');if(existing){setRecord(existing);setNotice('The owner-approved guest follow-up template is already approved.');return}throw Error('Save a draft first')}const result=await base44.entities.CommunicationTemplate.update(draft.id,{status:'approved',approved_by_user_id:user.id,approved_at:new Date().toISOString()});setRecord(result);setNotice('Template approved successfully. No email sent.')}catch(e){setError(e.message||'Approval failed')}finally{setBusy('')}};
