 useEffect(()=>{if(!tenant)return;let alive=true;(async()=>{setPreviewBusy(true);try{const r=await base44.functions.invoke("waitingList",{action:"admin_preview_email",signature:signatureOn,utility:utilityOn,utilityLinks:utilityKeys});if(alive)setPreviewHtml(r.data?.html||"")}catch(e){if(alive)setError(e?.response?.data?.error||e?.message||"Could not render the production email preview.")}finally{if(alive)setPreviewBusy(false)}})();return()=>{alive=false}},[tenant?.id,signatureOn,utilityOn,utilityKeys.join("|")]);
 const card=(k,label)=>!k?null:<div className="rounded-xl border bg-white p-5"><div className="flex items-start justify-between gap-4"><div><div className="text-xs font-bold uppercase tracking-wide text-muted-foreground">{label}</div><h3 className="font-bold text-lg mt-1">{k.name}</h3><div className="text-xs text-muted-foreground">Version {k.version} · {k.status}</div></div>{k.logos?.primary&&<img src={k.logos.primary} alt="" className="h-16 w-28 object-contain"/>}</div><div className="grid sm:grid-cols-2 gap-4 mt-4 text-sm"><div><b>Colours</b><div className="flex gap-2 mt-2">{["primary","secondary","accent","text"].map(key=>k.colours?.[key]?<div key={key} title={key+" "+k.colours[key]} className="h-8 w-8 rounded border" style={{background:k.colours[key]}}/>:null)}</div></div><div><b>Typography</b><div className="text-xs text-muted-foreground mt-2">{k.typography?.body_font||"Default"} · H1 {k.typography?.h1_size_px||"-"}px · H2 {k.typography?.h2_size_px||"-"}px · H3 {k.typography?.h3_size_px||"-"}px · Body {k.typography?.body_size_px||"-"}px</div></div></div>{k.contact&&<div className="mt-4 rounded-lg bg-slate-50 p-3 text-sm"><b>Signature:</b> {k.contact.signoff} {k.contact.name} · {k.contact.role} · {k.contact.organisation} · {k.contact.phone_whatsapp}</div>}</div>;
 const utilityOptions=[["website","Website"],["directory","RallyHub Directory"],["events","Events"],["feedback","Feedback"],["facebook","Facebook"],["instagram","Instagram"]];const toggleUtility=k=>setUtilityKeys(xs=>xs.includes(k)?xs.filter(x=>x!==k):[...xs,k]);const primary=tenant?.colours?.primary||"#2667f2",secondary=tenant?.colours?.secondary||"#facc15",contact=tenant?.contact||{};
 return <div className="space-y-3"><div className="rounded-xl border bg-white p-5"><h2 className="text-xl font-bold">Brand kits in use</h2><p className="text-sm text-muted-foreground mt-1">These are the stored rules the Communications Centre should use for logos, colours, type sizes, spacing, signature and footer treatment.</p>{busy&&<p className="text-sm mt-3">Loading brand kits…</p>}{error&&<p className="text-sm text-red-700 mt-3">{error}</p>}</div><div className="grid lg:grid-cols-2 gap-4">{card(tenant,"Active tenant brand")}{card(platform,"RallyHub platform brand")}</div>{tenant&&<div className="rounded-xl border bg-white p-5"><div className="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-4"><div><h3 className="font-bold text-lg">Basic email building blocks</h3><p className="text-sm text-muted-foreground mt-1">Inspection preview using the active Clare Brand Kit. The production waiting-list shell and existing Powered by RallyHub block stay unchanged.</p></div><div className="flex gap-2"><button type="button" onClick={()=>setSignatureOn(v=>!v)} className={"rounded-lg border px-3 py-2 text-sm font-bold "+(signatureOn?"bg-slate-900 text-white":"bg-white")}>Signature {signatureOn?"ON":"OFF"}</button><button type="button" onClick={()=>setUtilityOn(v=>!v)} className={"rounded-lg border px-3 py-2 text-sm font-bold "+(utilityOn?"bg-slate-900 text-white":"bg-white")}>Utility menu {utilityOn?"ON":"OFF"}</button></div></div><div className="grid lg:grid-cols-2 gap-5 mt-5"><div><div className="text-xs font-black uppercase tracking-wide text-muted-foreground">Utility menu candidates</div><div className="flex flex-wrap gap-2 mt-2">{utilityOptions.map(([key,label])=><button key={key} type="button" onClick={()=>toggleUtility(key)} className={"rounded-full border px-3 py-1.5 text-xs font-bold "+(utilityKeys.includes(key)?"bg-blue-50 border-blue-300 text-blue-900":"bg-white text-slate-500")}>{utilityKeys.includes(key)?"✓ ":""}{label}</button>)}</div><p className="mt-3 text-xs text-muted-foreground">Choose these visually for now. We can then define which are universal and which only appear for specific modules.</p></div><div className="rounded-xl border bg-[#f4f7fb] p-3">{previewBusy?<div className="min-h-[620px] flex items-center justify-center text-sm text-muted-foreground">Rendering the production email…</div>:previewHtml?<iframe title="Actual Clare basic email renderer" className="block w-full min-h-[720px] rounded bg-white" srcDoc={previewHtml} sandbox="allow-popups allow-popups-to-escape-sandbox allow-top-navigation-by-user-activation"/>:<div className="min-h-[620px] flex items-center justify-center text-sm text-red-700">Production preview unavailable.</div>}</div><div className="hidden"><div className="mx-auto max-w-md overflow-hidden rounded-xl border bg-white"><div style={{height:6,background:primary,borderBottom:`3px solid ${secondary}`}}></div><div className="p-5 text-center">{tenant.logos?.primary&&<img src={tenant.logos.primary} alt="Clare Pickleball" className="mx-auto h-16 w-24 object-contain"/>}<div className="mt-2 text-xl font-black">Clare Pickleball</div><div className="mt-1 text-[11px] font-bold tracking-[0.18em] text-slate-500">WAITING LIST</div></div><div className="px-6 pb-5 text-sm text-slate-700"><div className="font-bold text-lg text-slate-900">You&apos;re on the waiting list, John</div><p className="mt-3">Thanks for joining the <b>Clare Pickleball waiting list</b>.</p><p className="mt-2">We will contact you as soon as a suitable place becomes available.</p><p className="mt-2 text-xs text-slate-500"><b>This is not club membership.</b></p>{signatureOn&&<div className="mt-5 border-t pt-4 leading-6"><div>{contact.signoff||"Yours in sport,"}</div><div className="font-black" style={{color:primary}}>{contact.name||"Brian Moore"}</div><div className="font-bold" style={{color:secondary}}>{contact.role||"Chairperson"}, {contact.organisation||"Clare Pickleball"}</div><div className="mt-1 text-xs">{contact.phone_whatsapp||"087 810 0333"} · WhatsApp<br/>{contact.email||"clarepb2025@gmail.com"} · ClarePickleball.ie</div></div>}</div>{utilityOn&&utilityKeys.length>0&&<div className="border-t px-4 py-3 text-center text-[11px]">{utilityOptions.filter(([k])=>utilityKeys.includes(k)).map(([k,l],i)=><React.Fragment key={k}>{i>0&&<span className="mx-2 text-slate-300">·</span>}<span className="font-bold" style={{color:primary}}>{l}</span></React.Fragment>)}</div>}<div className="border-t bg-slate-50 px-4 py-4 text-center text-xs text-slate-500">Existing <b>Powered by RallyHub</b> production block remains here unchanged.</div></div></div></div></div>}</div>
