function WorkflowPanel(){const [active,setActive]=useState(null);return <ActionLibrary title="Workflows" intro="Choose a ready-made journey. Open it to review the trigger, steps and exit rules before activation." items={starterWorkflows} active={active} setActive={setActive} action="Open workflow"/>}
function PollPanel(){const [active,setActive]=useState(null);return <ActionLibrary title="Polls & Feedback" intro="Choose what you want to collect. The next screen is where questions, audience, closing time and reminders are configured." items={starterPolls} active={active} setActive={setActive} action="Create"/>}
function ActionLibrary({title,intro,items,active,setActive,action}){return <div className="space-y-4"><div className="rounded-xl border bg-white p-5"><h2 className="text-xl font-bold">{title}</h2><p className="text-sm text-muted-foreground mt-1">{intro}</p></div><div className="grid md:grid-cols-3 gap-4">{items.map(x=><button key={x[0]} onClick={()=>setActive(x)} className="text-left rounded-xl border bg-white p-5 hover:border-slate-500"><div className="font-bold">{x[1]}</div><p className="text-sm text-muted-foreground mt-2">{x[2]}</p><div className="font-semibold text-sm mt-4">{action} →</div></button>)}</div>{active&&<div className="rounded-xl border bg-white p-5"><div className="font-bold">{active[1]}</div><p className="text-sm mt-2">{active[2]}</p><div className="mt-4 rounded-lg bg-amber-50 border border-amber-200 p-3 text-sm">Configuration screen scaffolded; activation remains disabled until the Communications Engine migration gates are passed.</div></div>}</div>}
function FeaturePanel({tab}){const map={"Audiences":["Build audience","Use saved audience","Preview exact recipients","Review exclusions / suppressions"],"Delivery":["View queued messages","View sent / failed","Retry eligible failures","Stop remaining queued sends"],"Consent":["View preferences","Review suppressions","Double opt-in evidence","Purpose / channel permissions"],"Analytics":["Campaign performance","Action conversion","Failures / bounces","Communication pressure"],"Settings":["Brand & sender identity","Channels","Quiet hours","Rate limits / approvals"]};return <div className="rounded-xl border bg-white p-6"><h2 className="text-xl font-bold">{tab}</h2><div className="grid md:grid-cols-2 gap-3 mt-4">{(map[tab]||[]).map(x=><button key={x} className="text-left rounded-lg bg-slate-50 border p-4 text-sm font-semibold">{x}<span className="float-right">→</span></button>)}</div><p className="mt-5 text-xs text-muted-foreground">Each control is being built as an operator journey; production activation remains separate.</p></div>}

const OFFER_DEFAULT={subject:'Clare Pickleball · Please confirm your alternative session',body:'Hi {{guest_name}},\n\nWe can offer you an alternative pickleball session:\n\n{{session_details}}\n\nPlease confirm whether you can attend:\n{{confirmation_link}}\n\nYour original booking remains unchanged until you accept.',whatsapp:'Hi {{guest_name}}, Clare Pickleball can offer you {{session_details}}. Please confirm: {{confirmation_link}}'};
const SESSION_EDITOR_IDS=new Set(['session_booking_guest','session_booking_host','session_booking_organiser','session_private_invite','session_refund','guest_approved','guest_pending_admin']);
function SessionTemplateEditor({user,selected}){
 const [record,setRecord]=useState(null),[subject,setSubject]=useState(selected?.subject||''),[plain,setPlain]=useState(''),[html,setHtml]=useState(''),[whatsapp,setWhatsapp]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 useEffect(()=>{let live=true;setRecord(null);setSubject(selected?.subject||'');setPlain('');setHtml('');setWhatsapp('');if(!user?.active_tenant_id)return; base44.entities.CommunicationTemplate.filter({tenant_id:user.active_tenant_id,purpose:selected.id},'-created_date',30).then(rows=>{if(!live)return;const t=(rows||[]).find(x=>x.owner_scope==='tenant'&&x.status!=='retired');if(t){setRecord(t);setSubject(t.subject_template||'');setPlain(t.plain_text_template||'');setHtml(t.html_template||'');setWhatsapp(t.channel_templates?.whatsapp?.text||'')}}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[selected?.id,user?.active_tenant_id]);
 const save=async()=>{setBusy(true);setError('');try{const data={owner_scope:'tenant',tenant_id:user.active_tenant_id,module:'Session Bookings',purpose:selected.id,name:selected.name,version:record?.version||'1.0',status:'draft',subject_template:subject,plain_text_template:plain,html_template:html,channel_templates:{whatsapp:{text:whatsapp}},created_by_user_id:user.id};const result=record?await base44.entities.CommunicationTemplate.update(record.id,data):await base44.entities.CommunicationTemplate.create(data);setRecord(result);alert('Template saved. No email sent.')}catch(e){setError(e.message)}finally{setBusy(false)}};
 return <section className="rounded-xl border bg-white p-5 space-y-4"><h2 className="font-bold text-lg">{selected.name} · Shared template editor</h2><p className="text-sm text-muted-foreground">The Brand Kit and protected booking details are applied at delivery. HTML, plain text and WhatsApp versions are stored together. Saving does not send.</p>{error&&<p role="alert" className="text-red-700">{error}</p>}<label className="block text-sm font-semibold">Subject<input className="block w-full border rounded p-2 mt-1" value={subject} onChange={e=>setSubject(e.target.value)}/></label><label className="block text-sm font-semibold">Plain-text message<textarea rows={6} className="block w-full border rounded p-2 mt-1" value={plain} onChange={e=>setPlain(e.target.value)}/></label><label className="block text-sm font-semibold">HTML message<textarea rows={8} className="block w-full border rounded p-2 mt-1 font-mono text-xs" value={html} onChange={e=>setHtml(e.target.value)}/></label><label className="block text-sm font-semibold">WhatsApp message<textarea rows={3} className="block w-full border rounded p-2 mt-1" value={whatsapp} onChange={e=>setWhatsapp(e.target.value)}/></label><button type="button" disabled={busy} onClick={save} className="rounded bg-slate-900 text-white px-4 py-2">{busy?'Saving…':'Save template'}</button>{html&&<div><h3 className="font-semibold">HTML body preview (Brand Kit applied when sent)</h3><iframe title="Template HTML preview" className="w-full min-h-80 border rounded" sandbox="" srcDoc={html}/></div>}</section>
}
function GuestChangeOfferEditor({user,brandKit}){
 const [content,setContent]=useState(OFFER_DEFAULT),[saved,setSaved]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[view,setView]=useState('email'),[emailPreview,setEmailPreview]=useState('');
 useEffect(()=>{if(!user?.active_tenant_id)return;let live=true;base44.entities.CommunicationTemplate.filter({tenant_id:user.active_tenant_id,purpose:'guest_booking_change_offer'},'-created_date',30).then(rows=>{if(!live)return;const t=(rows||[]).find(x=>x.status!=='retired');if(t){setSaved(t);setContent({subject:t.subject_template||OFFER_DEFAULT.subject,body:t.plain_text_template||OFFER_DEFAULT.body,whatsapp:t.channel_templates?.whatsapp?.text||OFFER_DEFAULT.whatsapp})}}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[user?.active_tenant_id]);
 const save=async()=>{if(!user?.active_tenant_id)return;setBusy(true);setError('');try{if(!content.body.includes('{{confirmation_link}}')||!content.whatsapp.includes('{{confirmation_link}}'))throw Error('The private confirmation link must remain in both messages.');const data={owner_scope:'tenant',tenant_id:user.active_tenant_id,module:'Session Bookings',name:'Guest Booking — Alternative Session Offer',purpose:'guest_booking_change_offer',version:'1.0',status:'draft',subject_template:content.subject,plain_text_template:content.body,channel_templates:{whatsapp:{text:content.whatsapp}},merge_schema:{guest_name:'Guest name',session_details:'New date, venue and time',confirmation_link:'Private guest response link'},created_by_user_id:user.id};if(saved){await base44.entities.CommunicationTemplate.update(saved.id,data)}else{const row=await base44.entities.CommunicationTemplate.create(data);setSaved(row)}alert('Clare Pickleball template saved. Future alternative offers will use the saved wording. No message has been sent.')}catch(e){setError(e.message)}finally{setBusy(false)}};
 useEffect(()=>{let live=true;setEmailPreview('');if(view!=='email')return;const run=async()=>{try{const r=await base44.functions.invoke('guestSessionBooking',{action:'admin_change_offer_preview',subject:content.subject,messageBody:content.body});if(live){if(r.data?.error)throw Error(r.data.error);setEmailPreview(r.data?.previewHtml||'')}}catch(e){if(live)setError(e?.response?.data?.error||e.message||'Preview unavailable')}};run();return()=>{live=false}},[content.subject,content.body,view,user?.active_tenant_id]);
 const sample={guest_name:'Sample Guest',session_details:'Ennistymon Community Centre · Wednesday 14 October · 19:00–20:00',confirmation_link:'https://rallyhub.ie/booking-change/SAMPLE-LINK-NOT-ACTIVE'};
 const render=text=>String(text||'').replace(/{{(guest_name|session_details|confirmation_link)}}/g,(_,key)=>sample[key]);
 return <section className="rounded-xl border bg-white p-5 space-y-4"><h2 className="text-lg font-bold">Clare Pickleball · Alternative session offer</h2><p className="text-sm text-muted-foreground">Edit tenant wording and preview email or WhatsApp with sample data. The club-branded header, signature and Powered by RallyHub footer are applied by the booking email renderer. Saving does not send anything.</p>{error&&<p role="alert" className="text-red-700">{error}</p>}<label className="block text-sm font-semibold">Email subject<input className="mt-1 w-full rounded-lg border p-2" value={content.subject} onChange={e=>setContent(c=>({...c,subject:e.target.value}))}/></label><label className="block text-sm font-semibold">Email message<textarea rows={9} className="mt-1 w-full rounded-lg border p-2" value={content.body} onChange={e=>setContent(c=>({...c,body:e.target.value}))}/></label><label className="block text-sm font-semibold">WhatsApp message<textarea rows={4} className="mt-1 w-full rounded-lg border p-2" value={content.whatsapp} onChange={e=>setContent(c=>({...c,whatsapp:e.target.value}))}/></label><div className="flex gap-2"><button type="button" onClick={()=>setView('email')} className="rounded-lg border px-3 py-2">Preview email</button><button type="button" onClick={()=>setView('whatsapp')} className="rounded-lg border px-3 py-2">Preview WhatsApp</button><button type="button" disabled={busy} onClick={save} className="rounded-lg bg-slate-900 px-4 py-2 text-white">{busy?'Saving…':'Save tenant template'}</button></div><div className="rounded-xl border bg-slate-50 p-4"><p className="mb-2 text-xs font-bold">Sample {view==='email'?'email':'WhatsApp'} preview · Not sent</p>{view==='email'&&<><p className="font-bold">Clare Pickleball</p><p className="text-sm">{render(content.subject)}</p></>}{view==='email'?(emailPreview?<iframe title="Actual Clare Pickleball email HTML preview" srcDoc={emailPreview} className="w-full h-[750px] rounded-lg border bg-white" sandbox=""/>:<p className="text-sm">Loading branded email preview…</p>):<p className="mt-3 whitespace-pre-wrap text-sm">{render(content.whatsapp)}</p>}</div></section>
}
